//! Brazilian Portuguese (pt-BR) catalog: English source text → translation.
//!
//! Keys are the exact English texts passed to `tr`/`trf!` (and the names
//! that lower crates give to effects, transitions and generators).
//! Keep it sorted; a test checks that keys are unique.

use super::{Locale, Plural};

pub(super) const LOCALE: Locale = Locale {
    code: "pt-BR",
    native_name: "Português (Brasil)",
    decimal_separator: ',',
    thousands_separator: '.',
    plural,
    plural_forms: &[Plural::One, Plural::Other],
    texts: ENTRIES,
    context: CONTEXT,
    plurals: PLURALS,
    complete: true,
};

/// Portuguese (CLDR "pt"): one for 0 and 1, other for the rest.
fn plural(n: u64) -> Plural {
    if n <= 1 { Plural::One } else { Plural::Other }
}

